#!/bin/sh
# Hoot installer bootstrap, kit v0.1.0 (generated by `rummage installer pack`, CLDMV/rummage#472).
#
#   curl -fsSL https://cldmv.github.io/hoot-install/install.sh | sh
#
# It only makes sure a Node runtime exists, then runs the installer. Every download is pinned by SHA-256 in this file
# and checked before anything from it runs; a mismatch stops the install. Nothing here is secret.
#
# Options (environment): HOOT_HOME, HOOT_PORT, HOOT_VERSION, HOOT_SETUP_TOKEN, HOOT_GPU,
# HOOT_REGISTRY_TOKEN, HOOT_YES.

set -eu

# Everything is inside main, called on the last line, so a download cut short runs nothing.
main() {
	app_home="${HOOT_HOME:-$HOME/.hoot}"
	installer_url="https://cldmv.github.io/hoot-install/v0.1.0/installer.tgz"
	installer_sha256="a71cfa49c15be8b6edb037a9033f64a14f8f6e5cd3438d77f66cc50ae243c8fb"
	node_version="24.22.2"
	node_min_major=20

	say() { printf '%s\n' "$*" >&2; }
	die() { say "! $*"; exit 1; }

	fetch() { # url dest
		if command -v curl >/dev/null 2>&1; then curl -fsSL --proto '=https' --tlsv1.2 -o "$2" "$1"
		elif command -v wget >/dev/null 2>&1; then wget -q --https-only -O "$2" "$1"
		else die "neither curl nor wget is installed"; fi
	}
	sha256_of() {
		if command -v sha256sum >/dev/null 2>&1; then sha256sum "$1" | cut -d' ' -f1
		elif command -v shasum >/dev/null 2>&1; then shasum -a 256 "$1" | cut -d' ' -f1
		else die "no sha256sum or shasum to check downloads with"; fi
	}
	verified() { # file sha256 — removes the file when it does not match
		got="$(sha256_of "$1")"
		if [ "$got" != "$2" ]; then rm -f "$1"; die "checksum mismatch for $(basename "$1"): expected $2, got $got. Nothing was run."; fi
	}

	mkdir -p "$app_home"

	# A Node runtime: the system's when it is new enough, else a pinned portable one in the app folder.
	node_bin=""
	if command -v node >/dev/null 2>&1; then
		major="$(node -p 'process.versions.node.split(".")[0]' 2>/dev/null || echo 0)"
		if [ "$major" -ge "$node_min_major" ] 2>/dev/null; then node_bin="$(command -v node)"; fi
	fi
	if [ -z "$node_bin" ]; then
		os="$(uname -s)"; cpu="$(uname -m)"
		case "$os/$cpu" in
			Linux/x86_64|Linux/amd64) node_file="node-v24.22.2-linux-x64.tar.gz"; node_sha256="361718c444e49af2ca5a110c83ba6a8901143f23ab285ebbef0341f391f482a9" ;;
			Linux/aarch64|Linux/arm64) node_file="node-v24.22.2-linux-arm64.tar.gz"; node_sha256="95c264150aceb7f3437a29fd6984924f5f8d1511ea3cbd6c508b83f6c555dae2" ;;
			Darwin/x86_64) node_file="node-v24.22.2-darwin-x64.tar.gz"; node_sha256="d5e336d588c45be0c37dbd52cc29895593009ca4997a77a1fd02815131ed0e52" ;;
			Darwin/arm64) node_file="node-v24.22.2-darwin-arm64.tar.gz"; node_sha256="aa9549349e47dffaa42dcf95d6e06ade8c4bdafc980979883b88767670df385a" ;;
			*) die "no pinned Node runtime for $os/$cpu; install Node $node_min_major or newer and run: npx @cldmv/hoot-install" ;;
		esac
		node_dir="$app_home/node/$node_version"
		if [ ! -x "$node_dir/bin/node" ]; then
			say "Downloading Node $node_version ($node_file)…"
			mkdir -p "$app_home/node"
			fetch "https://nodejs.org/dist/v$node_version/$node_file" "$app_home/node/$node_file"
			verified "$app_home/node/$node_file" "$node_sha256"
			rm -rf "$node_dir.tmp" && mkdir -p "$node_dir.tmp"
			tar -xzf "$app_home/node/$node_file" -C "$node_dir.tmp" --strip-components=1
			rm -f "$app_home/node/$node_file"
			rm -rf "$node_dir" && mv "$node_dir.tmp" "$node_dir"
		fi
		node_bin="$node_dir/bin/node"
	fi

	# The installer itself, pinned by hash.
	dir="$app_home/installer/$installer_sha256"
	if [ ! -f "$dir/installer/bin/install.mjs" ]; then
		mkdir -p "$app_home/installer"
		archive="$app_home/installer/installer-$installer_sha256.tgz"
		fetch "$installer_url" "$archive"
		verified "$archive" "$installer_sha256"
		rm -rf "$dir.tmp" && mkdir -p "$dir.tmp"
		tar -xzf "$archive" -C "$dir.tmp"
		rm -f "$archive"
		rm -rf "$dir" && mv "$dir.tmp" "$dir"
	fi

	# Questions go to the terminal, not to the pipe this script came from.
	if [ -e /dev/tty ] && (: </dev/tty) 2>/dev/null; then
		exec "$node_bin" "$dir/installer/bin/install.mjs" "$@" </dev/tty
	fi
	exec "$node_bin" "$dir/installer/bin/install.mjs" "$@"
}

main "$@"
